-- Script para insertar productos transformados desde el archivo original (Lote completo 1-499)
-- Basado en: INSERT INTO productos (cod, cantidad, producto, categoria, precio_compra, precio_venta)

-- 1. Asegurarse de que las categorías existan (usando slugs)
ON CONFLICT (slug) DO NOTHING;

-- 2. Insertar productos transformados
WITH cat AS (SELECT id, name FROM public.categories)
ON CONFLICT (slug) DO UPDATE SET
  sku = EXCLUDED.sku,
  stock = EXCLUDED.stock,
  cost_price = EXCLUDED.cost_price,
  price = EXCLUDED.price,
  category_id = EXCLUDED.category_id,
  updated_at = NOW();
